mapper.select:
SELECT h.id, h.user_id AS userId, h.restaurant_id AS restaurantId, h.viewed_time AS viewedTime,
r.name AS name, r.logo_url AS imageUrl, r.description AS description, r.avg_rating AS avgRating, r.monthly_sales AS monthlySales
FROM user_history h LEFT JOIN restaurant r ON h.restaurant_id = r.id WHERE h.user_id = #{userId} ORDER BY h.viewed_time DESC LIMIT #{limit}
